SELECT m.*, p.name AS category FROM music_rank m INNER JOIN playlist_music pm ON m.id = pm.music_id INNER JOIN playlist p ON pm.playlist_id = p.id WHERE pm.playlist_id = #{playlistId}
AND (m.title LIKE CONCAT('%', #{keyword}, '%') OR m.artist LIKE CONCAT('%', #{keyword}, '%') OR m.album LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY m.star_rating DESC, m.create_time DESC

SELECT
    COUNT(*) AS total,
    COALESCE(AVG(CASE WHEN m.star_rating > 0 THEN m.star_rating END), 0) AS avgRating
FROM music_rank m

    INNER JOIN playlist_music pm ON m.id = pm.music_id



        AND pm.playlist_id = #{playlistId}


        AND (m.title LIKE CONCAT('%', #{keyword}, '%') OR m.artist LIKE CONCAT('%', #{keyword}, '%') OR m.album LIKE CONCAT('%', #{keyword}, '%'))


        AND m.artist = #{singer}


        AND m.star_rating >= #{starRatingMin}


        AND m.star_rating <= #{starRatingMax}



            AND m.star_rating > 0


            AND m.star_rating = 0



        AND m.album LIKE CONCAT('%', #{album}, '%')

SELECT pm.music_id AS musicId, p.name AS playlistName FROM playlist_music pm INNER JOIN playlist p ON pm.playlist_id = p.id WHERE pm.music_id IN
#{id}
ORDER BY pm.create_time ASC
